/* Generated by scripts/build-sw.mjs. Scope-relative URLs also support repository subpaths. */
const prefix = `running-log-shell:${self.registration.scope}:`;
const cacheName = prefix + '__BUILD_HASH__';
const urls = __PRECACHE_LIST__.map(
  (path) => new URL(path, self.registration.scope).href,
);
const shell = new URL('index.html', self.registration.scope).href;
self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(cacheName);
      // addAll fails atomically when any asset cannot be fetched. Never replace a working shell on partial install.
      await cache.addAll(
        urls.map((url) => new Request(url, { cache: 'reload' })),
      );
    })(),
  );
});
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith(prefix) && name !== cacheName)
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});
self.addEventListener('message', (event) => {
  if (event.data?.type === 'ACTIVATE_UPDATE') void self.skipWaiting();
});
self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (
    url.origin !== self.location.origin ||
    !url.href.startsWith(self.registration.scope)
  )
    return;
  const key = request.mode === 'navigate' ? shell : url.href;
  if (request.mode !== 'navigate' && !urls.includes(key)) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(cacheName);
      return (await cache.match(key)) ?? fetch(request);
    })(),
  );
});
